import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import {
  texture,
  positionLocal,
  normalLocal,
  uniform,
  uv,
  vec2,
  vec3,
  float,
  smoothstep,
  length,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, BoxGeometry, PlaneGeometry, CircleGeometry, Color, Texture, DirectionalLight } = THREE;

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'stat-tile-features';

  const width = 1.6;
  const height = 1.0;
  const depth = 0.14;

  // --- machined metal plate (base of the card) ---
  const plateGeo = new BoxGeometry(width, height, depth);
  const plateMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.ink),
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.35,
  });
  const plate = new Mesh(plateGeo, plateMat);
  root.add(plate);

  // --- accent edge (top bar, brightens on focus/hover) ---
  const edgeGeo = new BoxGeometry(width * 0.9, height * 0.045, depth * 1.05);
  const edgeMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 0.35,
    metalness: 0.3,
    roughness: 0.5,
  });
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.set(0, height / 2 - 0.03, depth / 2 + 0.005);
  root.add(edge);

  // --- tessellated displacement-mapped image plane (parallax-plane render mode) ---
  const imgGeo = new PlaneGeometry(width * 0.84, height * 0.66, 64, 64);
  const colorTexNode = texture(new Texture());
  const depthTexNode = texture(new Texture());
  const depthIntensity = uniform(0.035);

  const imgMat = new MeshStandardNodeMaterial({
    color: new Color(colors.surface),
    metalness: 0.12,
    roughness: 0.6,
  });
  imgMat.colorNode = colorTexNode;
  imgMat.positionNode = positionLocal.add(
    normalLocal.mul(depthTexNode.r.mul(depthIntensity))
  );

  const imagePlane = new Mesh(imgGeo, imgMat);
  imagePlane.position.set(0, -0.02, depth / 2 + 0.012);
  root.add(imagePlane);

  const loadedTextures = [];
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      colorTexNode.value = tex;
      loadedTextures.push(tex);
      imgMat.needsUpdate = true;
    });
  }
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthTexNode.value = tex;
      loadedTextures.push(tex);
      imgMat.needsUpdate = true;
    });
  }

  // --- radial contact shadow ---
  const shadowRadius = width * 0.82;
  const shadowGeo = new CircleGeometry(shadowRadius, 48);
  const dist = length(uv().sub(vec2(0.5, 0.5)));
  const shadowOpacity = float(1.0).sub(smoothstep(0.0, 0.5, dist)).mul(0.5);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true });
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = shadowOpacity;
  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.position.set(0, -height / 2 - 0.05, 0);
  root.add(contactShadow);

  // --- node-local rim light (accent tint) ---
  const rim = new DirectionalLight(new Color(colors.accent), 0.7);
  rim.position.set(-1.2, 0.6, 1.4);
  root.add(rim);

  // --- text content (value + label), rendered verbatim only if provided ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textNodes = [];
  let yCursor = 0.12;
  for (const item of items) {
    const role = item.role ?? 'body';
    const isValue = role === 'value' || role === 'headline' || role === 'metric';
    const t = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? (isValue ? 68 : 26),
      color: isValue ? colors.paper : colors.accent,
      align: 'center',
      maxWidthPx: 420,
    });
    t.position.set(0, yCursor, depth / 2 + 0.02);
    const scaleFactor = isValue ? 0.0052 : 0.0032;
    t.scale.setScalar(scaleFactor);
    root.add(t);
    textNodes.push(t);
    yCursor -= isValue ? 0.32 : 0.18;
  }

  // --- entrance: weighted-settle ---
  root.scale.setScalar(0.96);
  const entranceTl = gsap.timeline();
  entranceTl.to(root.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  });

  // --- cinematic primitive: parallax-scroll ---
  const primitiveHandles = [];
  const parallaxCfg = (config.cinematicPrimitives ?? []).find(
    (p) => p.name === 'parallax-scroll'
  );
  if (ctx.primitives?.['parallax-scroll']) {
    const params = parallaxCfg?.params ?? { intensity: 0.25 };
    const handle = ctx.primitives['parallax-scroll'](root, params);
    primitiveHandles.push(handle);
  }

  // --- interaction handlers ---
  const baseY = root.position.y;
  let hoverTl = null;
  let pressTl = null;

  function onPointerOver() {
    gsap.killTweensOf(root.position);
    gsap.killTweensOf(edgeMat);
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, {
      y: baseY + 0.15,
      duration: 0.5,
      ease: 'power3.out',
    }, 0);
    hoverTl.to(edgeMat, {
      emissiveIntensity: 1.1,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
  }

  function onPointerOut() {
    gsap.killTweensOf(root.position);
    gsap.killTweensOf(edgeMat);
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, {
      y: baseY,
      duration: 0.5,
      ease: 'power2.out',
    }, 0);
    hoverTl.to(edgeMat, {
      emissiveIntensity: 0.35,
      duration: 0.3,
      ease: 'power2.out',
    }, 0);
  }

  function onPointerDown() {
    gsap.killTweensOf(root.scale);
    pressTl = gsap.timeline();
    pressTl.to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(2)',
    });
  }

  function onPointerUp() {
    gsap.killTweensOf(root.scale);
    pressTl = gsap.timeline();
    pressTl.to(root.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.18,
      ease: 'back.out(2)',
    });
  }

  function onClick() {
    ctx.emit('hub-features.select', { node: 'features-stat-tile' });
  }

  root.userData.handlers = {
    pointerover: onPointerOver,
    pointerout: onPointerOut,
    pointerdown: onPointerDown,
    pointerup: onPointerUp,
    click: onClick,
  };

  root.userData.cleanup = function cleanup() {
    entranceTl.kill();
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();
    gsap.killTweensOf(root.position);
    gsap.killTweensOf(root.scale);
    gsap.killTweensOf(edgeMat);

    for (const h of primitiveHandles) {
      h?.timeline?.kill?.();
      h?.cleanup?.();
    }

    for (const t of loadedTextures) {
      t.dispose();
    }

    plateGeo.dispose();
    plateMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    imgGeo.dispose();
    imgMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();

    for (const t of textNodes) {
      t.geometry?.dispose?.();
      t.material?.dispose?.();
    }

    root.remove(rim);
  };

  return root;
}
